ALTER TABLE provider_connections ADD COLUMN media_options jsonb NOT NULL DEFAULT '{}';
ALTER TABLE assets DROP CONSTRAINT assets_size_check;
ALTER TABLE assets ADD CHECK(size BETWEEN 1 AND 8388608);
ALTER TABLE assets ADD COLUMN input_mode text NOT NULL DEFAULT 'original' CHECK(input_mode IN ('original','text','both','metadata'));
ALTER TABLE assets ADD COLUMN extracted_text text NOT NULL DEFAULT '';
ALTER TABLE asset_references ADD COLUMN input_mode text NOT NULL DEFAULT 'original' CHECK(input_mode IN ('original','text','both','metadata'));
ALTER TABLE asset_references ADD COLUMN extracted_text text NOT NULL DEFAULT '';
CREATE TABLE media_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),world_id uuid NOT NULL,actor_id uuid NOT NULL,operation_id uuid NOT NULL,input_hash text NOT NULL,kind text NOT NULL CHECK(kind IN ('image','edit','video','vision','stt','tts')),input jsonb NOT NULL,provider jsonb NOT NULL,state text NOT NULL DEFAULT 'queued',external_id text,result jsonb,error_code text,usage_id uuid REFERENCES background_usage(id) DEFERRABLE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,world_id,actor_id) REFERENCES world_characters(owner_id,world_id,id) DEFERRABLE,UNIQUE(owner_id,operation_id));
CREATE TABLE media_job_assets(job_id uuid NOT NULL REFERENCES media_jobs(id) DEFERRABLE,asset_id uuid NOT NULL REFERENCES assets(id) DEFERRABLE,PRIMARY KEY(job_id,asset_id));
CREATE TABLE voice_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),room_id uuid NOT NULL REFERENCES rooms(id) DEFERRABLE,actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,state text NOT NULL DEFAULT 'active',revision integer NOT NULL DEFAULT 1,settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE voice_turns(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES voice_sessions(id) DEFERRABLE,revision integer NOT NULL DEFAULT 1,transcript text NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'draft',run_id uuid REFERENCES runs(id) DEFERRABLE,stt_job_id uuid REFERENCES media_jobs(id) DEFERRABLE,tts_job_id uuid REFERENCES media_jobs(id) DEFERRABLE,played_ms integer NOT NULL DEFAULT 0,recording_id uuid REFERENCES assets(id) DEFERRABLE);
CREATE TABLE voice_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),room_id uuid NOT NULL REFERENCES rooms(id) DEFERRABLE,actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,state text NOT NULL DEFAULT 'pending',expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_at timestamptz NOT NULL DEFAULT now());
